  "signal_basis": {
    "component_id": "C003.signal_basis",
    "value": "Suggestive interview evidence informs consideration of competing explanations, including setup confusion, unavailable team information and waiting for a roster cycle.",
    "scope": "The eight interviews provide exploratory evidence, without establishing how common the explanations are.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
